CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.motor_performance_metrics
COMMENT 'THE motor loss ratio and its drivers. Use measure loss_ratio for any question about the motor loss ratio: it is the company definition approved by the Chief Actuary (paid plus outstanding case reserves plus IBNR, net of recoveries, over EARNED premium), accident-quarter basis, valued 31 October 2026. Segment, quarter, region and urbanity work on every measure. Peril, head of damage and large-loss flag describe claims only, so pair them with claim measures (incurred_claims, claim_count, severity), not with earned premium. The claims_operations_ratio (paid over WRITTEN premium) is the legacy weekly claims-ops number kept for reconciliation; it answers a different question and is not the loss ratio. All amounts GBP.'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_semantics.motor_loss_ratio_components

dimensions:
  - name: accident_quarter
    expr: accident_quarter
  - name: motor_segment
    expr: motor_segment
  - name: motor_segment_code
    expr: motor_segment_code
  - name: region_name
    expr: region_name
  - name: urbanity_code
    expr: urbanity_code
  - name: use_class_code
    expr: use_class_code
  - name: peril_code
    expr: peril_code
  - name: head_of_damage_code
    expr: head_of_damage_code
  - name: claim_feature_type_code
    expr: claim_feature_type_code
  - name: large_loss_flag
    expr: large_loss_flag
  - name: component_kind
    expr: component_kind

measures:
  - name: earned_premium
    expr: SUM(earned_premium)
  - name: written_premium
    expr: SUM(written_premium)
  - name: vehicle_years
    expr: SUM(vehicle_years)
  - name: claims_paid
    expr: SUM(claims_paid)
  - name: case_reserves
    expr: SUM(case_reserves)
  - name: ibnr
    expr: SUM(ibnr)
  - name: recoveries
    expr: SUM(recoveries)
  - name: claims_handling_costs
    expr: SUM(claims_handling_costs)
  - name: incurred_claims
    expr: SUM(claims_paid) + SUM(case_reserves) + SUM(ibnr) - SUM(recoveries)
  - name: loss_ratio
    expr: (SUM(claims_paid) + SUM(case_reserves) + SUM(ibnr) - SUM(recoveries)) / NULLIF(SUM(earned_premium), 0)
  - name: claim_count
    expr: SUM(claim_count)
  - name: frequency
    expr: SUM(claim_count) / NULLIF(SUM(vehicle_years), 0)
  - name: severity
    expr: (SUM(claims_paid) + SUM(case_reserves) - SUM(recoveries)) / NULLIF(SUM(claim_count), 0)
  - name: claims_operations_ratio
    expr: SUM(claims_paid) / NULLIF(SUM(written_premium), 0)
$$;
